Consistency Models.code:
// Strong Consistency: Read-after-write via primary
async function transferMoney(fromId, toId, amount) {
  // All reads/writes go to the primary DB
  const from = await primary.query(
    'SELECT balance FROM accounts WHERE id = $1 FOR UPDATE',
    [fromId]
  );
  if (from.balance < amount) throw new Error('Insufficient funds');

  await primary.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2',
    [amount, fromId]);
  await primary.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2',
    [amount, toId]);
}

// Eventual Consistency: Async replication
async function updateProfile(userId, data) {
  // Write to primary
  await primary.update('profiles', data, { id: userId });
  // Don't wait for replicas
  // Other users may see old data for a few seconds
}

// Read-Your-Writes: Track user's last write
class SessionConsistency {
  constructor(private userId: string) {}

  async write(key: string, value: any) {
    const timestamp = Date.now();
    await primary.set(key, value);
    // Store timestamp so reads can check freshness
    await redis.set(`last_write:${this.userId}`, timestamp);
  }

  async read(key: string): Promise<any> {
    const lastWrite = await redis.get(`last_write:${this.userId}`);
    // Read from replica that has data >= lastWrite
    return await replica.read(key, { minTimestamp: lastWrite });
  }
}

