Event-Driven Architecture.code:
// Order Service publishes events
async function createOrder(req, res) {
  const order = await db.transaction(async (trx) => {
    const order = await trx('orders').insert(req.body).returning('*');

    // Outbox pattern: write event in same transaction
    await trx('outbox').insert({
      aggregate_type: 'order',
      aggregate_id: order.id,
      event_type: 'OrderCreated',
      payload: JSON.stringify(order)
    });

    return order;
  });

  res.status(201).json(order);
}

// Outbox publisher (separate process)
async function publishOutboxEvents() {
  const events = await db('outbox').whereNull('published_at').limit(100);

  for (const event of events) {
    try {
      await kafka.produce({
        topic: event.event_type,
        messages: [{ key: event.aggregate_id, value: event.payload }]
      });
      await db('outbox')
        .where('id', event.id)
        .update({ published_at: new Date() });
    } catch (err) {
      console.error('Failed to publish event:', event.id, err);
      // Will retry on next poll
    }
  }
}

// Inventory Service consumes events
await kafka.consume('OrderCreated', async (event) => {
  const order = JSON.parse(event.value);
  for (const item of order.items) {
    await db('inventory')
      .where('product_id', item.productId)
      .decrement('quantity', item.quantity);
  }
  console.log(`Reserved inventory for order ${order.id}`);
});

Saga Pattern.code:
// ── Orchestration Saga ──
class OrderSagaOrchestrator {
  async execute(orderData: OrderData): Promise<void> {
    const sagaId = uuid();
    const context = { orderData, sagaId };

    try {
      // Step 1: Create Order
      const order = await this.orderService.createOrder(orderData);
      context.orderId = order.id;

      // Step 2: Reserve Payment
      await this.paymentService.reservePayment(context);

      // Step 3: Reserve Inventory
      await this.inventoryService.reserveInventory(context);

      // Step 4: Schedule Shipping
      await this.shippingService.scheduleShipping(context);

      // Step 5: Confirm Order
      await this.orderService.confirmOrder(order.id);

    } catch (err) {
      // Compensate: undo each completed step in reverse
      await this.compensate(context, err);
      throw err;
    }
  }

  private async compensate(context: SagaContext, err: Error): Promise<void> {
    console.error(`Saga ${context.sagaId} failed:`, err.message);

    if (context.orderId) {
      // Reverse order of operations
      if (context.shippingReserved) {
        await this.shippingService.cancelShipping(context);
      }
      if (context.inventoryReserved) {
        await this.inventoryService.releaseInventory(context);
      }
      if (context.paymentReserved) {
        await this.paymentService.releasePayment(context);
      }
      await this.orderService.cancelOrder(context.orderId);
    }
  }
}

// ── Choreography Saga ──
// Each service publishes events and listens for compensations
// Order Service creates order -> publishes OrderCreated
// Payment Service listens -> reserves payment -> publishes PaymentReserved
// Inventory Service listens -> reserves items -> publishes InventoryReserved
// Shipping Service listens -> schedules shipment -> publishes ShipmentScheduled
// If any step fails -> publishes CompensationRequired event
// All services listen and compensate their part

CQRS Pattern.code:
// ── Command Model (Write Side) ──
interface UpdateProfileCommand {
  userId: string;
  name: string;
  email: string;
  version: number;
}

class ProfileCommandHandler {
  async handle(command: UpdateProfileCommand): Promise<void> {
    // Validate business rules
    if (!isValidEmail(command.email)) {
      throw new ValidationError('Invalid email');
    }

    // Check for concurrent modifications (optimistic locking)
    const current = await this.eventStore.getLatestVersion('profile', command.userId);
    if (current !== command.version) {
      throw new ConcurrencyError('Profile was modified by another request');
    }

    // Append event to event store
    await this.eventStore.append('profile', command.userId, {
      type: 'ProfileUpdated',
      data: { name: command.name, email: command.email },
      timestamp: new Date()
    });
  }
}

// ── Query Model (Read Side) ──
class ProfileQueryHandler {
  // Denormalized read model
  async getProfileSummary(userId: string): Promise<ProfileSummary> {
    return this.readDb.query(
      `SELECT u.name, u.email, (
        SELECT COUNT(*) FROM orders o WHERE o.user_id = $1
      ) as order_count
      FROM user_profiles u WHERE u.user_id = $1`,
      [userId]
    );
  }

  // Different read projection
  async getProfileWithRecentActivity(userId: string): Promise<any> {
    return this.readDb.query(
      `SELECT * FROM user_profile_activity WHERE user_id = $1`,
      [userId]
    );
  }
}

