Database Sharding.code:
// Consistent Hashing (simplified)
class ConsistentHashRing {
  private ring: Map<number, string> = new Map();
  private sortedKeys: number[] = [];
  private virtualNodes = 100;

  addNode(nodeId: string): void {
    for (let i = 0; i < this.virtualNodes; i++) {
      const hash = this.hash(`${nodeId}:${i}`);
      this.ring.set(hash, nodeId);
    }
    this.sortedKeys = [...this.ring.keys()].sort((a, b) => a - b);
  }

  getNode(key: string): string {
    if (this.sortedKeys.length === 0) throw new Error('No nodes');
    const hash = this.hash(key);
    // Find the next node clockwise
    const idx = this.sortedKeys.findIndex(k => k >= hash);
    const targetKey = idx === -1 ? this.sortedKeys[0] : this.sortedKeys[idx];
    return this.ring.get(targetKey)!;
  }

  private hash(key: string): number {
    let hash = 0;
    for (let i = 0; i < key.length; i++) {
      hash = ((hash << 5) - hash) + key.charCodeAt(i);
      hash |= 0; // Convert to 32bit integer
    }
    return hash;
  }
}

// Usage: route queries to the right shard
const ring = new ConsistentHashRing();
ring.addNode('shard-a.postgres:5432');
ring.addNode('shard-b.postgres:5432');
ring.addNode('shard-c.postgres:5432');

async function findUserById(userId: string) {
  const shard = ring.getNode(userId);
  const pool = connectionPools[shard];
  return pool.query('SELECT * FROM users WHERE id = $1', [userId]);
}

Database Replication.code:
// Read/Write splitting in application
const pools = {
  primary: new Pool({ host: 'primary-db.example.com' }),
  replica1: new Pool({ host: 'replica1.example.com' }),
  replica2: new Pool({ host: 'replica2.example.com' })
};

const replicaPool = roundRobin([pools.replica1, pools.replica2]);

async function query(sql: string, params?: any[], isWrite?: boolean) {
  if (isWrite || sql.trim().toUpperCase().startsWith('INSERT') ||
      sql.trim().toUpperCase().startsWith('UPDATE') ||
      sql.trim().toUpperCase().startsWith('DELETE') ||
      sql.trim().toUpperCase().startsWith('CREATE') ||
      sql.trim().toUpperCase().startsWith('DROP') ||
      sql.trim().toUpperCase().startsWith('ALTER')) {
    return pools.primary.query(sql, params);
  }
  return replicaPool.query(sql, params);
}

// Read-your-writes: track last write timestamp
const lastWrites = new Map<string, number>();

async function writeWithTracking(userId: string, sql: string, params?: any[]) {
  const result = await pools.primary.query(sql, params);
  lastWrites.set(userId, Date.now());
  return result;
}

async function readWithConsistency(userId: string, sql: string, params?: any[]) {
  const lastWrite = lastWrites.get(userId);
  if (lastWrite && (Date.now() - lastWrite) < 1000) {
    // User just wrote — read from primary for consistency
    return pools.primary.query(sql, params);
  }
  return replicaPool.query(sql, params);
}

