// Node.js pg-pool configuration
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'app',
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool settings
  max: 20,                    // Max connections per pool
  idleTimeoutMillis: 30000,   // Close idle connections after 30s
  connectionTimeoutMillis: 2000,  // Error if can't get connection in 2s
  maxUses: 7500,              // Recycle connections periodically
  allowExitOnIdle: true
});

// Use pool.query for simple queries (auto-release)
app.get('/api/users', async (req, res) => {
  const { rows } = await pool.query('SELECT * FROM users LIMIT 100');
  res.json(rows);
});

// Use pool.connect for transactions
app.post('/api/orders', async (req, res) => {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const order = await client.query(
      'INSERT INTO orders (user_id, total) VALUES ($1, $2) RETURNING *',
      [req.userId, req.body.total]
    );
    await client.query('COMMIT');
    res.json(order.rows[0]);
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // Return to pool
  }
});

// Monitor pool
setInterval(() => {
  console.log({
    totalCount: pool.totalCount,
    idleCount: pool.idleCount,
    waitingCount: pool.waitingCount
  });
}, 5000);

Event Sourcing.code:
// Event sourced bank account
interface AccountEvent {
  type: string;
  amount: number;
  timestamp: Date;
}

class Account {
  private balance = 0;
  private events: AccountEvent[] = [];
  private snapshotVersion = 0;

  // Rebuild state from events
  static loadFromHistory(events: AccountEvent[], snapshot?: { balance: number; version: number }) {
    const account = new Account();
    if (snapshot) {
      account.balance = snapshot.balance;
      account.snapshotVersion = snapshot.version;
    }
    // Replay events after snapshot
    for (const event of events) {
      account.apply(event);
    }
    return account;
  }

  deposit(amount: number) {
    this.apply({ type: 'Deposited', amount, timestamp: new Date() });
  }

  withdraw(amount: number) {
    if (this.balance < amount) throw new Error('Insufficient funds');
    this.apply({ type: 'Withdrawn', amount, timestamp: new Date() });
  }

  private apply(event: AccountEvent) {
    this.events.push(event);
    switch (event.type) {
      case 'Deposited':
        this.balance += event.amount;
        break;
      case 'Withdrawn':
        this.balance -= event.amount;
        break;
    }
  }

  getBalance() { return this.balance; }
  getEvents() { return [...this.events]; }

  // Store events in database
  async save(eventStore: EventStore, accountId: string) {
    for (const event of this.events) {
      await eventStore.append('account', accountId, event);
    }
  }
}

// Query: get balance at a specific point in time
async function getBalanceAt(accountId: string, date: Date): Promise<number> {
  const events = await eventStore.getEventsUntil('account', accountId, date);
  const account = Account.loadFromHistory(events);
  return account.getBalance();
}

