// Cache-Aside Pattern (most common)
class UserService {
  async getUser(id: string): Promise<User> {
    // 1. Try cache
    const cached = await cache.get(`user:${id}`);
    if (cached) return JSON.parse(cached);

    // 2. Cache miss — load from DB
    const user = await db.query('SELECT * FROM users WHERE id = $1', [id]);

    // 3. Store in cache with TTL
    await cache.setex(`user:${id}`, 3600, JSON.stringify(user));

    return user;
  }

  async updateUser(id: string, data: Partial<User>): Promise<User> {
    // Update database first
    const user = await db.query(
      'UPDATE users SET name = $1, email = $2 WHERE id = $3 RETURNING *',
      [data.name, data.email, id]
    );

    // Invalidate cache (delete, not update!)
    // Next read will cache the fresh data
    await cache.del(`user:${id}`);

    // Optionally publish invalidation event
    await eventBus.publish('cache.invalidate', {
      pattern: `user:${id}`,
      action: 'delete'
    });

    return user;
  }
}

// Write-Through Pattern
async function writeThrough(key: string, data: any, dbSave: () => Promise<void>) {
  // Write to both
  await Promise.all([
    cache.set(key, JSON.stringify(data)),
    dbSave()
  ]);
}

// Write-Behind (Write-Back) Pattern
const writeQueue = new Map<string, any>();

async function writeBehind(key: string, data: any, dbSave: () => Promise<void>) {
  // Write to cache immediately
  await cache.set(key, JSON.stringify(data));

  // Queue DB write
  writeQueue.set(key, { data, dbSave });
}

// Background: flush queue to DB every second
setInterval(async () => {
  for (const [key, { dbSave }] of writeQueue) {
    try {
      await dbSave();
      writeQueue.delete(key);
    } catch (err) {
      console.error('Write-behind failed:', key, err);
    }
  }
}, 1000);

