// 2. Rate Limiter (Sliding Window)
async function checkRateLimit(key: string, maxRequests: number, windowMs: number): Promise<boolean> {
  const now = Date.now();
  const windowStart = now - windowMs;

  // Remove old entries
  await redis.zremrangebyscore(`ratelimit:${key}`, 0, windowStart);

  // Count requests in window
  const count = await redis.zcard(`ratelimit:${key}`);

  if (count >= maxRequests) {
    return false; // Rate limited
  }

  // Add current request
  await redis.zadd(`ratelimit:${key}`, now, `${now}:${Math.random()}`);
  await redis.expire(`ratelimit:${key}`, Math.ceil(windowMs / 1000));

  return true;
}

// 3. Distributed Lock
async function acquireLock(lockName: string, ttlMs: number): Promise<string | null> {
  const lockId = crypto.randomUUID();
  const acquired = await redis.set(`lock:${lockName}`, lockId, 'PX', ttlMs, 'NX');
  return acquired ? lockId : null;
}

async function releaseLock(lockName: string, lockId: string): Promise<void> {
  // Lua script: only release if we own the lock
  const script = `
    if redis.call("get", KEYS[1]) == ARGV[1] then
      return redis.call("del", KEYS[1])
    else
      return 0
    end
  `;
  await redis.eval(script, 1, `lock:${lockName}`, lockId);
}

