// RabbitMQ consumer with acknowledgment
const amqp = require('amqplib');

async function startConsumer() {
  const connection = await amqp.connect('amqp://localhost');
  const channel = await connection.createChannel();

  const queue = 'order.processing';
  await channel.assertQueue(queue, {
    durable: true,  // Survive broker restart
    deadLetterExchange: 'dlx',  // Failed messages go to DLQ
    maxPriority: 10
  });

  // Prefetch: process one message at a time (fair dispatch)
  await channel.prefetch(1);

  channel.consume(queue, async (msg) => {
    if (!msg) return;

    try {
      const order = JSON.parse(msg.content.toString());
      console.log(`Processing order ${order.id}`);

      await processOrder(order);

      // Acknowledge successful processing
      channel.ack(msg);
    } catch (err) {
      console.error('Failed to process message:', err.message);

      // Reject and don't requeue (sends to DLQ)
      channel.nack(msg, false, false);
    }
  });
}

// Idempotent consumer (handle at-least-once delivery)
const processedMessages = new Set();

async function handleMessage(msg) {
  const messageId = msg.properties.messageId;

  // Deduplication check
  if (processedMessages.has(messageId)) {
    console.log('Duplicate message, skipping');
    channel.ack(msg);
    return;
  }

  await db.transaction(async (trx) => {
    // Process message AND mark as processed in same transaction
    await processPayment(trx, msg);
    await trx('processed_messages').insert({ message_id: messageId });
  });

  processedMessages.add(messageId);
  channel.ack(msg);
}

