const { SQSClient, SendMessageCommand, ReceiveMessageCommand, DeleteMessageCommand } = require('@aws-sdk/client-sqs');

const sqs = new SQSClient({ region: 'us-east-1' });
const QUEUE_URL = 'https://sqs.us-east-1.amazonaws.com/123456789012/my-queue';

// Send message
async function sendMessage(order) {
  await sqs.send(new SendMessageCommand({
    QueueUrl: QUEUE_URL,
    MessageBody: JSON.stringify(order),
    MessageGroupId: order.userId, // Required for FIFO
    MessageDeduplicationId: order.id // Required for FIFO
  }));
}

// Receive and process
async function processMessages() {
  const response = await sqs.send(new ReceiveMessageCommand({
    QueueUrl: QUEUE_URL,
    MaxNumberOfMessages: 10,
    WaitTimeSeconds: 20, // Long polling
    VisibilityTimeout: 30
  }));

  if (!response.Messages) return;

  for (const message of response.Messages) {
    try {
      const order = JSON.parse(message.Body);
      await processOrder(order);

      // Delete after successful processing
      await sqs.send(new DeleteMessageCommand({
        QueueUrl: QUEUE_URL,
        ReceiptHandle: message.ReceiptHandle
      }));
    } catch (err) {
      console.error('Processing failed:', err);
      // Don't delete — message will reappear after visibility timeout
      // After maxReceiveCount, it goes to DLQ
    }
  }
}

