// Outbox Pattern: Atomic DB operation + event publishing

async function createOrder(orderData) {
  // Use a database transaction to atomically:
  // 1. Insert the order
  // 2. Insert an outbox event
  const result = await db.transaction(async (trx) => {
    const [order] = await trx('orders').insert(orderData).returning('*');

    await trx('outbox').insert({
      aggregate_type: 'order',
      aggregate_id: order.id,
      event_type: 'OrderCreated',
      payload: JSON.stringify(order),
      created_at: new Date()
    });

    return order;
  });

  return result;
}

// Background: publish outbox events
async function publishOutbox() {
  const events = await db('outbox')
    .whereNull('published_at')
    .orderBy('created_at')
    .limit(100)
    .forUpdate()  // Prevent double-publishing
    .skipLocked();

  for (const event of events) {
    try {
      await messageBroker.publish(event.event_type, event.payload);
      await db('outbox')
        .where('id', event.id)
        .update({
          published_at: new Date(),
          attempts: db.raw('attempts + 1')
        });
    } catch (err) {
      console.error(`Failed to publish event ${event.id}:`, err.message);
      if (event.attempts >= 5) {
        // Move to dead letter for manual inspection
        await db('outbox_errors').insert(event);
        await db('outbox').where('id', event.id).del();
      }
    }
  }
}

// Run publisher every second
setInterval(publishOutbox, 1000);

