Distributed Locking.code:
// Redis distributed lock (simplified Redlock)
class DistributedLock {
  constructor(private redis: Redis, private ttlMs: number = 30000) {}

  async acquire(lockName: string, retryDelayMs = 100, maxRetries = 10): Promise<string | null> {
    const lockId = crypto.randomUUID();

    for (let attempt = 0; attempt < maxRetries; attempt++) {
      const acquired = await this.redis.set(
        `lock:${lockName}`,
        lockId,
        'PX',
        this.ttlMs,
        'NX'
      );

      if (acquired) {
        console.log(`Acquired lock ${lockName} (${lockId})`);
        return lockId;
      }

      // Exponential backoff
      await sleep(retryDelayMs * Math.pow(2, attempt) + Math.random() * 50);
    }

    return null; // Failed to acquire
  }

  async release(lockName: string, lockId: string): Promise<void> {
    // Lua script: atomic check-and-delete
    const script = `
      if redis.call("get", KEYS[1]) == ARGV[1] then
        return redis.call("del", KEYS[1])
      else
        return 0
      end
    `;

    await this.redis.eval(script, 1, `lock:${lockName}`, lockId);
    console.log(`Released lock ${lockName}`);
  }

  // Auto-release with async context
  async withLock<T>(lockName: string, fn: () => Promise<T>): Promise<T> {
    const lockId = await this.acquire(lockName);
    if (!lockId) {
      throw new Error(`Could not acquire lock: ${lockName}`);
    }

    // Auto-extend lock if operation is long
    const extendTimer = setInterval(async () => {
      await this.redis.expire(`lock:${lockName}`, this.ttlMs / 1000);
    }, this.ttlMs / 3);

    try {
      return await fn();
    } finally {
      clearInterval(extendTimer);
      await this.release(lockName, lockId);
    }
  }
}

// Usage: ensure only one cron runner
const lock = new DistributedLock(redis);

app.post('/admin/run-backup', async (req, res) => {
  try {
    const result = await lock.withLock('daily-backup', async () => {
      console.log('Starting backup...');
      await runDatabaseBackup();
