Circuit Breaker Pattern.code:
// Circuit Breaker Implementation
class CircuitBreaker {
  private state: 'CLOSED' | 'OPEN' | 'HALF_OPEN' = 'CLOSED';
  private failureCount = 0;
  private successCount = 0;
  private lastFailureTime = 0;
  private readonly failureThreshold: number;
  private readonly successThreshold: number;
  private readonly openTimeout: number;
  private readonly halfOpenMaxCalls: number;

  constructor(
    private action: () => Promise<any>,
    options: {
      failureThreshold?: number;
      successThreshold?: number;
      openTimeout?: number;
      halfOpenMaxCalls?: number;
    } = {}
  ) {
    this.failureThreshold = options.failureThreshold || 5;
    this.successThreshold = options.successThreshold || 3;
    this.openTimeout = options.openTimeout || 30000;
    this.halfOpenMaxCalls = options.halfOpenMaxCalls || 1;
  }

  async call(): Promise<any> {
    if (this.state === 'OPEN') {
      if (Date.now() - this.lastFailureTime >= this.openTimeout) {
        console.log('Circuit half-open: testing service');
        this.state = 'HALF_OPEN';
        this.successCount = 0;
      } else {
        throw new CircuitBreakerOpenError('Circuit breaker is open');
      }
    }

    try {
      const result = await this.action();
      this.onSuccess();
      return result;
    } catch (err) {
      this.onFailure();
      throw err;
    }
  }

  private onSuccess(): void {
    if (this.state === 'HALF_OPEN') {
      this.successCount++;
      if (this.successCount >= this.successThreshold) {
        console.log('Circuit closed: service recovered');
        this.state = 'CLOSED';
        this.failureCount = 0;
      }
    } else {
      this.failureCount = 0; // Reset on consecutive success
    }
  }

  private onFailure(): void {
    this.failureCount++;
    this.lastFailureTime = Date.now();

    if (this.failureCount >= this.failureThreshold) {
      console.log('Circuit open: too many failures');
      this.state = 'OPEN';
    }
  }

  getState() { return this.state; }
}

class CircuitBreakerOpenError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CircuitBreakerOpenError';
  }
}

