    return { status: 'deferred' };
  }
  throw err;
}

Bulkhead Pattern.code:
// Thread pool isolation with Node.js worker threads
const { Worker } = require('worker_threads');

class BulkheadPool {
  private active = 0;
  private queue: Array<{ resolve: Function; reject: Function; task: Function }> = [];

  constructor(private maxConcurrent: number, private maxQueue: number) {}

  async execute<T>(task: () => Promise<T>): Promise<T> {
    if (this.active >= this.maxConcurrent) {
      if (this.queue.length >= this.maxQueue) {
        throw new BulkheadFullError('Bulkhead queue is full');
      }

      return new Promise((resolve, reject) => {
        this.queue.push({ resolve, reject, task });
      });
    }

    return this.runTask(task);
  }

  private async runTask<T>(task: () => Promise<T>): Promise<T> {
    this.active++;
    try {
      return await task();
    } finally {
      this.active--;
      this.processQueue();
    }
  }

  private processQueue(): void {
    if (this.queue.length > 0 && this.active < this.maxConcurrent) {
      const next = this.queue.shift()!;
      this.runTask(next.task).then(next.resolve).catch(next.reject);
    }
  }
}

// Different bulkheads for different services
const bulkheads = {
  payment: new BulkheadPool(5, 10),    // Max 5 concurrent payment calls
  inventory: new BulkheadPool(10, 20),  // Max 10 concurrent inventory calls
  email: new BulkheadPool(3, 5)        // Max 3 concurrent email calls
};

// Usage
async function checkout(order: Order) {
  const [payment, inventory] = await Promise.all([
    bulkheads.payment.execute(() => paymentService.charge(order.total)),
    bulkheads.inventory.execute(() => inventoryService.reserve(order.items))
  ]);

  // Don't block on email — fire and forget
  bulkheads.email.execute(() => emailService.send(order.email, 'Order confirmed'))
    .catch(err => console.error('Email failed:', err));

  return { payment, inventory };
}

