// Sliding Window Rate Limiter with Redis
class SlidingWindowRateLimiter {
  constructor(private redis: Redis) {}

  async checkLimit(
    key: string,
    maxRequests: number,
    windowSeconds: number
  ): Promise<{ allowed: boolean; remaining: number; resetAt: number }> {
    const now = Date.now();
    const windowStart = now - windowSeconds * 1000;
    const redisKey = `ratelimit:${key}`;

    // Use Redis sorted set: score = timestamp, member = timestamp:random
    // 1. Remove old entries outside the window
    await this.redis.zremrangebyscore(redisKey, 0, windowStart);

    // 2. Count current requests in window
    const count = await this.redis.zcard(redisKey);

    // 3. Set TTL on the key (cleanup)
    await this.redis.expire(redisKey, windowSeconds + 1);

    if (count >= maxRequests) {
      // Get the oldest entry's timestamp for Retry-After
      const oldest = await this.redis.zrange(redisKey, 0, 0, 'WITHSCORES');
      const oldestTime = oldest.length >= 2 ? parseInt(oldest[1]) : now;
      const resetAt = Math.ceil(oldestTime / 1000) + windowSeconds;

      return { allowed: false, remaining: 0, resetAt };
    }

    // Add current request
    await this.redis.zadd(redisKey, now, `${now}:${Math.random()}`);

    return {
      allowed: true,
      remaining: maxRequests - count - 1,
      resetAt: Math.ceil(now / 1000) + windowSeconds
    };
  }
}

// Express middleware
const rateLimiter = new SlidingWindowRateLimiter(redis);

app.use(async (req, res, next) => {
  const key = req.user?.id || req.ip;
  const result = await rateLimiter.checkLimit(key, 100, 60);

  // Set standard rate limit headers
  res.setHeader('X-RateLimit-Limit', '100');
  res.setHeader('X-RateLimit-Remaining', String(result.remaining));
  res.setHeader('X-RateLimit-Reset', String(result.resetAt));

  if (!result.allowed) {
    res.setHeader('Retry-After', String(result.resetAt - Math.floor(Date.now() / 1000)));
    return res.status(429).json({
      error: 'Too many requests',
      message: `Rate limit exceeded. Retry after ${result.resetAt - Math.floor(Date.now() / 1000)} seconds.`
    });
  }

  next();
});

