    res.setHeader('Sunset', 'Sat, 01 Jan 2027 00:00:00 GMT');
    res.setHeader('Deprecation', 'true');
    res.setHeader('Link', '</api/docs/v2>; rel="successor-version"');
  }

  next();
});

