// URL Shortener implementation
const express = require('express');
const crypto = require('crypto');
const app = express();

// ── ID Generation ──
const BASE62 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';

function encodeBase62(num: number): string {
  let encoded = '';
  while (num > 0) {
    encoded = BASE62[num % 62] + encoded;
    num = Math.floor(num / 62);
  }
  return encoded.padStart(7, '0');
}

// Use Redis INCR for unique IDs
async function generateShortId(): Promise<string> {
  const id = await redis.incr('url_counter');
  return encodeBase62(id);
}

// ── URL Shortening ──
app.post('/api/shorten', express.json(), async (req, res) => {
  const { url, customAlias, expiresInDays } = req.body;

  // Validate URL
  try {
    new URL(url);
  } catch {
    return res.status(400).json({ error: 'Invalid URL' });
  }

  // Check custom alias
  if (customAlias) {
    const existing = await redis.get(`url:${customAlias}`);
    if (existing) {
      return res.status(409).json({ error: 'Custom alias already taken' });
    }
  }

  const shortId = customAlias || await generateShortId();

  // Store in Redis (fast reads) and PostgreSQL (persistence)
  const ttl = expiresInDays ? expiresInDays * 86400 : null;

  const pipeline = redis.pipeline();
  pipeline.set(`url:${shortId}`, url);
  if (ttl) pipeline.expire(`url:${shortId}`, ttl);
  await pipeline.exec();

  // Async: persist to DB
  db.query(
    'INSERT INTO short_urls (id, long_url, expires_at) VALUES ($1, $2, $3) ON CONFLICT DO NOTHING',
    [shortId, url, ttl ? new Date(Date.now() + ttl * 1000) : null]
  ).catch(err => console.error('DB persist failed:', err));

  res.json({
    shortUrl: `https://short.url/${shortId}`,
    shortId,
    longUrl: url
  });
});

// ── Redirect ──
app.get('/:id', async (req, res) => {
  const { id } = req.params;

  // Try cache first
  const url = await redis.get(`url:${id}`);
  if (url) {
    // Async analytics
    recordClick(id, req).catch(() => {});
    return res.redirect(301, url);
  }

  // Cache miss: load from DB
  const result = await db.query('SELECT long_url FROM short_urls WHERE id = $1', [id]);
  if (result.rows.length === 0) {
    return res.status(404).send('URL not found');
  }

  const longUrl = result.rows[0].long_url;
  // Populate cache
  await redis.set(`url:${id}`, longUrl);

  recordClick(id, req);
  res.redirect(301, longUrl);
});

