// WebSocket Chat Server (Node.js)
const WebSocket = require('ws');
const redis = require('redis');

const wss = new WebSocket.Server({ port: 8080 });
const publisher = redis.createClient();
const subscriber = redis.createClient();

// Track connected users: userId -> WebSocket
const connections = new Map<string, WebSocket[]>();

// Subscribe to Redis channel for cross-server messages
subscriber.subscribe('chat:messages', (message) => {
  const { conversationId, senderId, text, timestamp, messageId } = JSON.parse(message);

  // Deliver to all connected recipients in this conversation
  // (Assume we have a mapping of conversation -> user IDs)
  broadcastToConversation(conversationId, {
    type: 'new_message',
    senderId,
    text,
    timestamp,
    messageId
  }, senderId); // Don't echo back to sender
});

wss.on('connection', (ws, req) => {
  const userId = authenticateUser(req); // JWT token from query params

  // Add to connections
  if (!connections.has(userId)) connections.set(userId, []);
  connections.get(userId)!.push(ws);

  // Update presence
  publisher.set(`presence:${userId}`, 'online', 'EX', 120);

  ws.on('message', async (data) => {
    const message = JSON.parse(data.toString());

    switch (message.type) {
      case 'send_message':
        const msgId = generateMessageId();

        // Store message in database
        await db.query(
          'INSERT INTO messages (id, conversation_id, sender_id, text, created_at) VALUES ($1, $2, $3, $4, $5)',
          [msgId, message.conversationId, userId, message.text, new Date()]
        );

        // Publish to Redis (cross-server delivery)
        publisher.publish('chat:messages', JSON.stringify({
          conversationId: message.conversationId,
          senderId: userId,
          text: message.text,
          timestamp: Date.now(),
          messageId: msgId
        }));
        break;

      case 'typing':
        // Ephemeral: don't store, just broadcast to conversation
        broadcastToConversation(message.conversationId, {
          type: 'typing',
          userId,
          isTyping: message.isTyping
        }, userId);
        break;
    }
  });

  ws.on('close', () => {
    const userConnections = connections.get(userId);
    if (userConnections) {
      const idx = userConnections.indexOf(ws);
      if (idx >= 0) userConnections.splice(idx, 1);
      if (userConnections.length === 0) {
        connections.delete(userId);
        publisher.set(`presence:${userId}`, JSON.stringify({ status: 'offline', lastSeen: Date.now() }));
      }
    }
  });
});

function broadcastToConversation(conversationId: string, message: any, excludeUserId?: string) {
  // Get user IDs for this conversation
  // This could be from a cache or DB
  const userIds = getConversationMembers(conversationId);

  for (const userId of userIds) {
    if (userId === excludeUserId) continue;
    const userConns = connections.get(userId);
    if (userConns) {
      for (const ws of userConns) {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(JSON.stringify(message));
        }
      }
    }
  }
}

