// ── Upload Service ──
app.post('/api/upload', upload.single('file'), async (req, res) => {
  const { originalname, size, buffer, mimetype } = req.file;
  const fileId = uuid();

  // Split file into 64MB chunks
  const CHUNK_SIZE = 64 * 1024 * 1024; // 64MB
  const chunks = [];

  for (let offset = 0; offset < buffer.length; offset += CHUNK_SIZE) {
    const chunk = buffer.slice(offset, offset + CHUNK_SIZE);
    const chunkId = uuid();
    const hash = crypto.createHash('sha256').update(chunk).digest('hex');

    // Apply erasure coding (simplified: replicate to 3 nodes)
    const storageNodes = consistentHash.getNodes(chunkId, 3);

    await Promise.all(storageNodes.map(node =>
      storageClient.upload(node, `chunks/${chunkId}`, chunk)
    ));

    chunks.push({ chunkId, offset, size: chunk.length, hash, nodes: storageNodes });
  }

  // Store metadata
  await db.query(`
    INSERT INTO files (id, name, size, mime_type, owner_id, chunks, created_at)
    VALUES ($1, $2, $3, $4, $5, $6, NOW())
  `, [fileId, originalname, size, mimetype, req.userId, JSON.stringify(chunks)]);

  res.json({ fileId, name: originalname, size });
});

// ── Download Service ──
app.get('/api/download/:fileId', async (req, res) => {
  const file = await db.query('SELECT * FROM files WHERE id = $1', [req.params.fileId]);
  if (file.rows.length === 0) return res.status(404).json({ error: 'File not found' });

  const { name, size, mime_type, chunks } = file.rows[0];
  const chunkList = JSON.parse(chunks);

  res.setHeader('Content-Type', mime_type);
  res.setHeader('Content-Disposition', `attachment; filename="${name}"`);
  res.setHeader('Content-Length', size);

  // Stream chunks
  for (const chunk of chunkList) {
    // Try primary node, fallback to replicas
    for (const node of chunk.nodes) {
      try {
        const data = await storageClient.download(node, `chunks/${chunk.chunkId}`);
        // Verify integrity
        const hash = crypto.createHash('sha256').update(data).digest('hex');
        if (hash === chunk.hash) {
          res.write(data);
          break; // Success, move to next chunk
        }
      } catch (err) {
        console.error(`Failed to fetch chunk ${chunk.chunkId} from ${node}`);
        // Try next replica
      }
    }
  }

  res.end();
});

