// Payment processing with idempotency
app.post('/api/payments', express.json(), async (req, res) => {
  const idempotencyKey = req.headers['idempotency-key'];

  if (!idempotencyKey) {
    return res.status(400).json({ error: 'idempotency-key header required' });
  }

  // Check idempotency
  const existing = await redis.get(`idempotency:${idempotencyKey}`);
  if (existing) {
    return res.status(200).json(JSON.parse(existing));
  }

  const { amount, currency, paymentMethodId, orderId, description } = req.body;

  // Create transaction record
  const transactionId = uuid();

  await db.query(`
    INSERT INTO transactions (id, order_id, amount, currency, status, idempotency_key, created_at)
    VALUES ($1, $2, $3, $4, 'INITIATED', $5, NOW())
  `, [transactionId, orderId, amount, currency, idempotencyKey]);

  try {
    // Call Payment Service Provider
    const paymentIntent = await stripe.paymentIntents.create({
      amount: Math.round(amount * 100), // cents
      currency,
      payment_method: paymentMethodId,
      confirm: true,
      metadata: { transactionId, orderId }
    });

    // Update transaction
    await db.query(
      `UPDATE transactions SET status = 'SUCCEEDED', provider_ref = $1, updated_at = NOW() WHERE id = $2`,
      [paymentIntent.id, transactionId]
    );

    const response = {
      transactionId,
      status: 'succeeded',
      amount,
      currency,
      providerRef: paymentIntent.id
    };

    // Cache idempotency response (TTL 24h)
    await redis.setex(`idempotency:${idempotencyKey}`, 86400, JSON.stringify(response));

    // Publish event
    await eventBus.publish('payment.completed', {
      transactionId,
      orderId,
      amount,
      currency
    });

    res.json(response);

  } catch (err) {
    // Handle specific Stripe errors
    const status = err.type === 'StripeCardError' ? 'FAILED' : 'ERROR';

    await db.query(
      `UPDATE transactions SET status = $1, error = $2, updated_at = NOW() WHERE id = $3`,
      [status, err.message, transactionId]
    );

    await eventBus.publish('payment.failed', {
      transactionId,
      orderId,
      error: err.message
    });

    res.status(402).json({
      error: 'Payment failed',
      message: err.message,
      transactionId
    });
  }
});

